STP_CHECK_CONFIG_KEYS = frozenset(
    ("bridges", "links", "delay", "bridge", "ports", "age", "max_frame")
)
STP_CHECK_FRAME_KEYS = frozenset(
    ("t", "port", "src", "dst", "vlan", "length", "fcs", "alignment")
)


def validate_stp_check_config(config):
    if (
        not isinstance(config, dict)
        or frozenset(config) != STP_CHECK_CONFIG_KEYS
    ):
        raise InvalidInput("bad config")
    # bridges/links/delay/bridge/ports/age 与 forward-stp 契约一致，复用其全量校验
    bridges, links, delay, bridge, ports, age = validate_forward_stp_config(
        {key: config[key] for key in FORWARD_STP_CONFIG_KEYS}
    )
    max_frame = config["max_frame"]
    if (
        not _is_int(max_frame)
        or not FRAME_CHECK_MIN_MAX_FRAME
        <= max_frame
        <= FRAME_CHECK_MAX_MAX_FRAME
    ):
        raise InvalidInput("bad max_frame")
    return bridges, links, delay, bridge, ports, age, max_frame


def validate_stp_check_events(events, ports, link_ids):
    if not isinstance(events, list):
        raise InvalidInput("events must be a list")
    names = {port["name"] for port in ports}
    result = []
    prev_t = None
    for event in events:
        if not isinstance(event, dict):
            raise InvalidInput("bad event")
        keys = frozenset(event)
        if keys == STP_EVENT_KEYS:
            t = event["t"]
            lid = event["id"]
            up = event["up"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(lid, str) or not lid or lid not in link_ids:
                raise InvalidInput("bad event id")
            if not isinstance(up, bool):
                raise InvalidInput("bad up")
            result.append(("link", t, lid, up))
        elif keys == STP_CHECK_FRAME_KEYS:
            t = event["t"]
            port = event["port"]
            src = event["src"]
            dst = event["dst"]
            vlan = event["vlan"]
            length = event["length"]
            fcs = event["fcs"]
            alignment = event["alignment"]
            if not _is_int(t) or t < 0:
                raise InvalidInput("bad t")
            if prev_t is not None and t < prev_t:
                raise InvalidInput("t not monotonic")
            if not isinstance(port, str) or port not in names:
                raise InvalidInput("unknown port")
            if not valid_mac(src):
                raise InvalidInput("bad src")
            if not valid_dst_mac(dst):
                raise InvalidInput("bad dst")
            if vlan is not None and not _valid_vlan_id(vlan):
                raise InvalidInput("bad vlan")
            if not _is_int(length) or length < 0:
                raise InvalidInput("bad length")
            if not isinstance(fcs, bool):
                raise InvalidInput("bad fcs")
            if not isinstance(alignment, bool):
                raise InvalidInput("bad alignment")
            result.append(
                ("frame", t, port, src, dst, vlan, length, fcs, alignment)
            )
        else:
            raise InvalidInput("bad event")
        prev_t = t
    return result


def forward_stp_check(
    bridges, links, delay, bridge_name, ports, age, max_frame, events,
    observer=None,
):
    """observer 非 None 时（record/replay）逐事件记录 applied 与输出：

    链路项仅 up 实际改变时 applied，output 恒 None；帧项恒 applied，
    output 为对应 results 项（键序 t,class,action,ports）。
    """
    by_id = {link["id"]: link for link in links}
    by_name = {port["name"]: port for port in ports}
    port_link = {}  # 本桥桥链路口名 -> link
    for link in links:
        for end_bridge, end_port in (link["x"], link["y"]):
            if end_bridge == bridge_name:
                port_link[end_port] = link
    fdb = {}  # (vlan, mac) -> [port, seen]
    port_stats = {
        port["name"]: {
            "rx": 0,
            "tx": 0,
            "drop": 0,
            "good": 0,
            "runt": 0,
            "giant": 0,
            "alignment": 0,
            "bad_fcs": 0,
        }
        for port in ports
    }
    vlan_stats = {}
    for port in ports:
        for vlan in port["allowed"]:
            vlan_stats.setdefault(vlan, {"rx": 0, "tx": 0, "drop": 0})
    results = []
    if observer is not None:  # record/replay：逐事件记录 applied 与输出
        observer["items"] = []

    previous = {}  # (bridge, port) -> 上一轮角色
    since = {}  # (bridge, port) -> 获得当前 root/designated 角色的时刻
    roles = {name: {} for name in bridges}

    def converge(t):
        _, _, new_roles = stp_converge(bridges, links)
        for name in bridges:
            for port, role in new_roles[name].items():
                key = (name, port)
                if role in STP_TIMED_ROLES:
                    if previous.get(key) != role:  # 同角色不重计时
                        since[key] = t
                else:
                    since.pop(key, None)
        previous.clear()
        for name in bridges:
            for port, role in new_roles[name].items():
                previous[(name, port)] = role
        roles.clear()
        for name in bridges:
            roles[name] = new_roles[name]

    def forwarding_ports(t):
        result = set()
        for name, link in port_link.items():
            key = (bridge_name, name)
            role = roles[bridge_name][name]
            if (
                by_name[name]["up"]
                and link["up"]
                and role in STP_TIMED_ROLES
                and t - since[key] >= 2 * delay
            ):
                result.add(name)
        return result

    def port_status(name, t):
        """返回 (物理 up, STP 状态)；边缘口恒为 up 即 forwarding。"""
        port = by_name[name]
        link = port_link.get(name)
        if link is None:
            return port["up"], ("forwarding" if port["up"] else "down")
        if not port["up"]:
            return False, "down"
        if not link["up"]:
            return False, "disabled"
        role = roles[bridge_name][name]
        if role in STP_TIMED_ROLES:
            elapsed = t - since[(bridge_name, name)]
            if elapsed < delay:
                state = "discarding"
            elif elapsed < 2 * delay:
                state = "learning"
            else:
                state = "forwarding"
        else:
            state = "discarding"  # alternate
        return True, state

    converge(0)
    for item in events:
        t = item[1]
        for key in [k for k, (_, seen) in fdb.items() if t - seen >= age]:
            del fdb[key]
        if item[0] == "link":
            _, t, lid, up = item
            applied = by_id[lid]["up"] != up  # up 实际改变才 applied
            old_forwarding = forwarding_ports(t)
            by_id[lid]["up"] = up
            converge(t)
            for name in old_forwarding - forwarding_ports(t):
                for key in [k for k, (p, _) in fdb.items() if p == name]:
                    del fdb[key]
            if observer is not None:  # 链路项：output 恒 None
                observer["items"].append(
                    {"kind": "link", "t": t, "applied": applied,
                     "output": None}
                )
            continue
        _, t, port_name, src, dst, tag, length, fcs, alignment = item
        port_stats[port_name]["rx"] += 1
        if length < FRAME_CHECK_RUNT_LENGTH:
            cls = "runt"
        elif length > max_frame:
            cls = "giant"
        elif not alignment:
            cls = "alignment"
        elif not fcs:
            cls = "bad_fcs"
        else:
            cls = "good"
        port_stats[port_name][cls] += 1

#!/usr/bin/env python3
"""link-flow-decode 子命令回归。

link-flow-decode 使用 link-wire-decode 的配置与混合事件（link/advance/
{t,port,data} 原始帧、显式时钟、queue_bytes），但每口额外声明布尔
flow_control。合法 PAUSE 帧（未带标签、目的 01:80:c2:00:00:01、类型
0x8808、操作码 0x0001、长度 64、保留字节全零、FCS 正确）在入端口本地
终止：不学习、不参与 VLAN 转发；端口 up/full 且启用流控时暂停发送到
t+ceil(quanta*512000/rate)，已开始帧继续完成，未开始副本整体后移且
顺序不变，新副本接队尾，非零覆盖、零值在当前帧完成后恢复，链路离开
up 清除暂停；否则 pause_unsupported 且不改队列；控制帧非法输出
malformed_pause。坏 FCS/短帧/超长帧沿用既有分类优先级。

仅用标准库；端到端驱动 `python switch.py link-flow-decode CONFIG EVENTS`。
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest
import zlib

HERE = os.path.dirname(os.path.abspath(__file__))
SWITCH = os.path.join(HERE, "switch.py")

BCAST = "ff:ff:ff:ff:ff:ff"
PAUSE_DST = "01:80:c2:00:00:01"
MAC1 = "00:00:00:00:00:01"
MAC2 = "00:00:00:00:00:02"


def port(name, pvid=1, allowed=None, untagged=None, mode="access",
         rates=None, modes=None, queue_bytes=1000000, flow_control=True):
    if allowed is None:
        allowed = [pvid] if mode == "access" else sorted(
            set([pvid] + (untagged or []))
        )
    if untagged is None:
        untagged = [pvid] if mode == "access" else []
    return {
        "name": name,
        "mode": mode,
        "pvid": pvid,
        "allowed": allowed,
        "untagged": untagged,
        "rates": [10, 100, 1000, 10000] if rates is None else rates,
        "modes": ["half", "full"] if modes is None else modes,
        "queue_bytes": queue_bytes,
        "flow_control": flow_control,
    }


def config(ports=None, age=100, max_frame=1518, delay=10):
    return {
        "ports": ports if ports is not None else [port("p1"), port("p2")],
        "age": age,
        "max_frame": max_frame,
        "delay": delay,
    }


def link(t, p, admin=True, peer=True, rates=None, modes=None):
    return {
        "t": t,
        "port": p,
        "admin": admin,
        "peer": peer,
        "rates": [10, 100, 1000, 10000] if rates is None else rates,
        "modes": ["half", "full"] if modes is None else modes,
    }


def advance(t):
    return {"t": t, "advance": True}


def mac_bytes(mac):
    return bytes(int(part, 16) for part in mac.split(":"))


def raw_frame(t, p, dst=BCAST, src=MAC1, ethertype=0x0800, payload=b"",
              fcs_good=True):
    body = mac_bytes(dst) + mac_bytes(src) + ethertype.to_bytes(2, "big") \
        + payload
    fcs = (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
    if not fcs_good:
        fcs = b"\xff\xff\xff\xff"
    return {"t": t, "port": p, "data": (body + fcs).hex()}


def data_event(t, p, dst=BCAST, src=MAC2, payload_len=46):
    return raw_frame(
        t, p, dst, src, 0x0800, b"\x00" * payload_len, True
    )


def pause_event(t, p, quanta, opcode=0x0001, reserved_byte=0, pad=42):
    body = (
        mac_bytes(PAUSE_DST) + mac_bytes(MAC1) + b"\x88\x08"
        + opcode.to_bytes(2, "big") + quanta.to_bytes(2, "big")
        + bytes([reserved_byte]) * pad
    )
    fcs = (zlib.crc32(body) & 0xFFFFFFFF).to_bytes(4, "little")
    return {"t": t, "port": p, "data": (body + fcs).hex()}


def raw_pause_event(t, p, body_no_fcs):
    fcs = (zlib.crc32(body_no_fcs) & 0xFFFFFFFF).to_bytes(4, "little")
    return {"t": t, "port": p, "data": (body_no_fcs + fcs).hex()}


def _pause_prefix():
    return mac_bytes(PAUSE_DST) + mac_bytes(MAC1) + b"\x88\x08"


def pause_body_opcode(opcode, quanta=10, pad=42):
    return _pause_prefix() + opcode.to_bytes(2, "big") \
        + quanta.to_bytes(2, "big") + b"\x00" * pad


def pause_body_reserved(value, quanta=10, pad=42):
    return _pause_prefix() + b"\x00\x01" + quanta.to_bytes(2, "big") \
        + bytes([value]) * pad


def pause_body_len(total_with_fcs, quanta=10, reserved=0):
    # 返回总长 total_with_fcs 的帧体（不含 FCS），保持目的/类型/操作码
    target_body = total_with_fcs - 4
    fixed = _pause_prefix() + b"\x00\x01" + quanta.to_bytes(2, "big")
    return fixed + bytes([reserved]) * (target_body - len(fixed))


def write_inputs(config_doc, events):
    tmp = tempfile.mkdtemp()
    cfg = os.path.join(tmp, "config.json")
    evt = os.path.join(tmp, "events.json")
    with open(cfg, "wb") as handle:
        handle.write(json.dumps(config_doc).encode("utf-8"))
    with open(evt, "wb") as handle:
        handle.write(json.dumps(events).encode("utf-8"))
    return tmp, cfg, evt


def run_cli(config_doc, events, *limits):
    tmp, cfg, evt = write_inputs(config_doc, events)
    proc = subprocess.run(
        [sys.executable, SWITCH, "link-flow-decode", cfg, evt,
         *[str(x) for x in limits]],

def _result_bytes(result):
    """stdout 载荷：紧凑 UTF-8 JSON 加一个 LF。"""
    return (
        json.dumps(result, ensure_ascii=False, separators=(",", ":")).encode(
            "utf-8"
        )
        + b"\n"
    )


def _cmd_record(
